+void fused_experts_cpu_local_skip(
+    at::Tensor& out,
+    at::Tensor& hidden_states,
+    at::Tensor& w1,
+    at::Tensor& w2,
+    at::Tensor& topk_weights,
+    at::Tensor& topk_ids,
+    at::Tensor& expert_map,
